from decimal import Decimal, DecimalException, localcontext
import re

def generate():
    return []

def check(reply, clue):
    answer = reply.split()
    expected = clue.split()
    if len(answer) != 1 or len(expected) != 1:
        return False
    number = r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?"
    if any(re.fullmatch(number, token) is None for token in answer):
        return False
    try:
        with localcontext() as ctx:
            ctx.prec = 60
            tolerance = Decimal("1e-7")
            for actual, target in zip(answer, expected):
                actual, target = Decimal(actual), Decimal(target)
                if not actual.is_finite() or not target.is_finite():
                    return False
                if abs(actual - target) > max(tolerance, tolerance * abs(target)):
                    return False
    except (DecimalException, ValueError):
        return False
    return True
